import{_ as i,l,o as e,c as n,v as r,p as s,x as t,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"价格效率度量：方差比与自相关","description":"","frontmatter":{"title":"价格效率度量：方差比与自相关","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/price-efficiency-measures.md","filePath":"quant/price-efficiency-measures.md","lastUpdated":1789023840000}'),p={name:"quant/price-efficiency-measures.md"};function m(u,a,V,R,q,_){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="价格效率度量-方差比与自相关" tabindex="-1">价格效率度量：方差比与自相关 <a class="header-anchor" href="#价格效率度量-方差比与自相关" aria-label="Permalink to &quot;价格效率度量：方差比与自相关&quot;">​</a></h1><div class="epigraph"><p>随机游走要求 $q$ 期收益的方差是单期方差的 $q$ 倍。方差比偏离 1，就是可预测的暂时成分或过度反应留下的痕迹——它度量效率，不解释痕迹从哪来。</p><footer>—— Lo and MacKinlay, Stock Market Prices Do Not Follow Random Walks: Evidence from a Simple Specification Test, Review of Financial Studies, 1988</footer></div><p><a href="/quant/gonzalo-granger">Gonzalo–Granger</a>在协整系统里抽出永久趋势。缺口是：只有一条价格时，怎样用二阶矩判断暂时成分有多大？方差比（VR）与自相关是最旧也最便携的效率度量。Lo 与 MacKinlay（1988）给出异方差稳健的 VR 检验；微观结构把同一工具用到日内：负的一阶自相关往往是弹跳，而不是可交易的反转 alpha。本课不把 VR 写成新的定价模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Hasbrouck 的信息含量与 PT 权重都需要一个动态系统。很多比较只想要一个标量：这只股票、这一时段，价格有多接近随机游走。若收益不相关，则 \\(\\mathrm{Var}(r_{t,t+q})=q\\,\\mathrm{Var}(r_{t,t+1})\\)，VR\\((q)=1\\)。VR\\(\\lt 1\\) 来自负自相关（弹跳、库存回复、过度反应后纠正）；VR\\(\\gt 1\\) 来自正自相关（反应不足、订单流持续、趋势）。问题是：在微观结构噪声下，怎样避免把 Roll 弹跳叫做「市场无效」，以及怎样选择 \\(q\\) 使 VR 比较的是同一经济对象。</p><p>效率在此是<strong>价格相对随机游走的距离</strong>，不是「投资者是否理性」的哲学判断，也不是执行是否便宜。</p><h3 id="与-hasbrouck-定价误差的关系" tabindex="-1">与 Hasbrouck 定价误差的关系 <a class="header-anchor" href="#与-hasbrouck-定价误差的关系" aria-label="Permalink to &quot;与 Hasbrouck 定价误差的关系&quot;">​</a></h3><p>Hasbrouck（1993）把定价误差方差当作市场质量：价格 = 有效随机游走 + 平稳误差。VR 是误差在收益二阶矩上的投影：强负自相关抬高定价误差、压低 VR。两者同方向，但 VR 不估计误差的水平方差，只看不同地平线方差的比。不要把 VR 缺 1 的部分直接叫 \\(\\lambda\\) 或 PIN。</p><p><span class="marginnote">Cochrane（1988）在宏观持久性上用过方差比；Lo–MacKinlay 把它做成股票收益的规范检验。日内应用必须改采样：日历时间与<a href="/quant/event-time">事件时间</a>会给出不同的 VR。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义</p> \\[\\mathrm{VR}(q)=\\frac{\\mathrm{Var}(r_t+\\cdots+r_{t+q-1})}{q\\,\\mathrm{Var}(r_t)}. \\]<p>它等于 \\(1+2\\sum_{k=1}^{q-1}(1-k/q)\\rho_k\\)。报告 VR 即报告加权自相关。Lo–MacKinlay 的统计量在异方差下仍有极限分布，适合波动聚类的收益。重叠 \\(q\\) 期收益提高效率，但要修正相关。</p><p>微观结构用法：用中点收益而不是成交价，减弱 Roll 弹跳；或先按报价方向调整成交价。比较开盘一小时与午盘，比较 tick 粗细不同的股票。\\(q\\) 取 1 分钟对 10 分钟、或 1 笔对 10 笔。事件时间 \\(q\\) 衡量的是「多少次成交之后噪声被平均掉」，更靠近效率的交易时钟。</p><h3 id="可预测性不是免费午餐" tabindex="-1">可预测性不是免费午餐 <a class="header-anchor" href="#可预测性不是免费午餐" aria-label="Permalink to &quot;可预测性不是免费午餐&quot;">​</a></h3><p>VR\\(\\neq 1\\) 只说明线性可预测。能否交易取决于价差、深度与速度：弹跳的负相关被买卖价差吃掉，这正是 Roll 模型的内容。把 VR 当策略信号，会把市场质量度量误用成 alpha。Amihud–Mendelson 的价差溢价是截面期望，与一只股票日内 VR 没有一一对应。</p>',16)),(e(),s(h,null,{default:t(()=>[d(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20Rho%5B%22%E6%94%B6%E7%9B%8A%E8%87%AA%E7%9B%B8%E5%85%B3%20%CF%81k%22%5D%20--%3E%20VR%5B%22VR(q)%20%3D%201%20%2B%20%E5%8A%A0%E6%9D%83%20%CF%81%22%5D%0A%20%20VR%20--%3E%7C%22%E5%B0%8F%E4%BA%8E%201%22%7C%20Neg%5B%22%E5%BC%B9%E8%B7%B3%20%2F%20%E5%9B%9E%E5%A4%8D%20%2F%20%E8%BF%87%E5%BA%A6%E5%8F%8D%E5%BA%94%22%5D%0A%20%20VR%20--%3E%7C%22%E5%A4%A7%E4%BA%8E%201%22%7C%20Pos%5B%22%E5%8F%8D%E5%BA%94%E4%B8%8D%E8%B6%B3%20%2F%20%E6%B5%81%E7%9A%84%E6%8C%81%E7%BB%AD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>暂时成分在短 \\(q\\) 上把 VR 拉离 1，永久信息在长 \\(q\\) 上把 VR 拉回 1（若暂时是平稳的）。这与 PT 分解一致：长期方差由共同趋势贡献。知情交易若立刻写入价格，不产生自相关；知情交易若被拆开平滑释放（多期 Kyle），订单流持续会造成短正自相关，VR 略大于 1。噪声交易若被库存吸收后回复，短 VR 小于 1。因此 VR 的符号不能单方面证明「有没有内幕」——两种理论都能让它偏离 1，只是方向与地平线不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>非线性可预测、波动率变化、跳变，都会破坏 VR 的解释。涨跌停把收益截断，VR 不可比。样本短时 \\(q\\) 不能太大。多市场时单序列 VR 忽略领先滞后，应回到 IS / PT。把日度 VR 与日内 VR 画在一张图上比较「效率」，单位已经不是同一个过程。</p><p><span class="marginnote">Lo–MacKinlay 拒绝随机游走，并不等于拒绝有效市场：有效市场允许风险溢价时变。微观结构课里我们只把 VR 当暂时成分的矩，不把它升级成资产定价检验。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>方差比把各阶自相关收成一个效率标量；VR\\(=1\\) 是随机游走的二阶矩含义。</li><li>日内负相关首先要排除弹跳，再用中点或事件时间比较市场质量。</li><li>VR 偏离不能单独命名为库存或信息；它与 Hasbrouck 定价误差同方向、不同对象。</li><li>可预测性不等于可交易 alpha。</li><li>出处：Lo and MacKinlay, <em>Review of Financial Studies</em>, 1988；定价误差见 Hasbrouck, <em>Journal of Finance</em>, 1993。</li></ul>',7))])}const B=i(p,[["render",m]]);export{f as __pageData,B as default};
